/**
 * Resolve smaller card/thumb siblings for local product WebPs.
 * Generated by `npm run optimize:image-variants` as `*.card.webp` / `*.thumb.webp`.
 */

const allWebp = import.meta.glob<string>("@/assets/products/**/*.webp", {
  eager: true,
  import: "default",
});

const urlToPath = new Map<string, string>();
for (const [modulePath, url] of Object.entries(allWebp)) {
  urlToPath.set(url, modulePath);
}

function siblingUrl(fullUrl: string, kind: "card" | "thumb") {
  const modulePath = urlToPath.get(fullUrl);
  if (!modulePath) return fullUrl;
  if (/\.(card|thumb)\.webp$/i.test(modulePath)) return fullUrl;
  const sibling = modulePath.replace(/\.webp$/i, `.${kind}.webp`);
  return allWebp[sibling] ?? fullUrl;
}

export function cardImageUrl(fullUrl: string | undefined | null) {
  if (!fullUrl) return "";
  return siblingUrl(fullUrl, "card");
}

export function thumbImageUrl(fullUrl: string | undefined | null) {
  if (!fullUrl) return "";
  return siblingUrl(fullUrl, "thumb");
}

/** Prefer card for ~viewport cards; keep full as 2x fallback. */
export function productSrcSet(fullUrl: string | undefined | null) {
  if (!fullUrl) return undefined;
  const card = cardImageUrl(fullUrl);
  if (card === fullUrl) return undefined;
  return `${card} 420w, ${fullUrl} 840w`;
}
